import { computed, ref, watch, type Ref } from 'vue'
import { useUserStore } from '@/stores/user'
import type { CardForm } from './useCardForm'

type Draft = { version: 1; key: string; updatedAt: number; baseline: string; form: CardForm }

// 本地备份只属于一个已通过权限检查的编辑会话，不能随着路由或账号变化重新归属。
export function useCardDraft(form: Ref<CardForm>) {
  const user = useUserStore()
  const pending = ref<Draft | null>(null)
  const savedAt = ref(0)
  const error = ref('')
  let binding: { key: string; token: string; userId: string; baseline: string } | undefined
  let paused = false
  const active = () => binding && binding.token === user.token && binding.userId === user.userId
  const serverChanged = computed(() => Boolean(pending.value && pending.value.baseline !== binding?.baseline))

  function suspend() {
    binding = undefined
    pending.value = null
    savedAt.value = 0
    error.value = ''
  }
  // token 先于 userInfo 更新，必须同步解绑，不能把旧表单写到新账号名下。
  watch(() => [user.token, user.userId], suspend, { flush: 'sync' })

  function clear() {
    if (!active()) return
    try {
      localStorage.removeItem(binding!.key)
      pending.value = null
      savedAt.value = 0
      error.value = ''
    } catch { error.value = '无法清理本地草稿，请检查浏览器存储设置。' }
  }

  function flush(): boolean {
    if (!active()) return false
    if (pending.value) return true
    try {
      const snapshot = JSON.stringify(form.value)
      if (snapshot === binding!.baseline) { clear(); return !error.value }
      const draft: Draft = { version: 1, key: binding!.key, updatedAt: Date.now(), baseline: binding!.baseline, form: form.value }
      localStorage.setItem(binding!.key, JSON.stringify(draft))
      savedAt.value = draft.updatedAt
      error.value = ''
      return true
    } catch {
      error.value = '本地草稿备份失败，请先保存条目，暂勿刷新或关闭页面。'
      return false
    }
  }

  function bind(projectId: string, cardId: string) {
    suspend()
    if (!user.token || !user.userId || !projectId) return
    const key = `world-card-draft:v1:${[user.userId, projectId, cardId || 'new'].map(encodeURIComponent).join(':')}`
    binding = { key, token: user.token, userId: user.userId, baseline: JSON.stringify(form.value) }
    try {
      const raw = localStorage.getItem(key)
      if (!raw) return
      const draft = JSON.parse(raw) as Draft
      // 严格检查表单字段和集合，损坏或不同版本的数据不能进入编辑器。
      const candidate = draft.form
      const strings = ['title', 'type', 'coverImage', 'description'] as const
      const lists = ['galleryImages', 'attributes', 'tags', 'relations', 'contentBlocks', 'timelineEvents'] as const
      if (draft.version !== 1 || draft.key !== key || !Number.isFinite(draft.updatedAt) || typeof draft.baseline !== 'string'
        || !candidate || strings.some(field => typeof candidate[field] !== 'string')
        || lists.some(field => !Array.isArray(candidate[field])) || !candidate.content || typeof candidate.content !== 'object' || Array.isArray(candidate.content)
        || [...candidate.galleryImages, ...candidate.tags].some(value => typeof value !== 'string')
        || candidate.attributes.some(value => !value || typeof value.key !== 'string' || typeof value.type !== 'string')
        || candidate.relations.some(value => !value || typeof value.targetCardId !== 'string' || typeof value.relationType !== 'string')
        || candidate.contentBlocks.some(value => !value || typeof value.cardId !== 'string')
        || candidate.timelineEvents.some(value => !value || typeof value.date !== 'string' || typeof value.title !== 'string')) throw new Error('invalid draft')
      if (JSON.stringify(candidate) === binding.baseline) { clear(); return }
      pending.value = draft
    } catch { error.value = '本地草稿无法读取，未恢复任何内容。可以继续编辑并重新备份。' }
  }

  function restore() {
    if (!active() || !pending.value) return
    paused = true
    form.value = JSON.parse(JSON.stringify(pending.value.form))
    pending.value = null
    paused = false
    flush()
  }
  function acceptSaved() {
    clear()
    if (binding) binding.baseline = JSON.stringify(form.value)
  }
  watch(form, () => { if (!paused) flush() }, { deep: true, flush: 'sync' })
  return { pending, savedAt, error, serverChanged, bind, suspend, restore, clear, flush, acceptSaved }
}

// src/composables/世界观管理/useCardEditor.ts
import { ref, computed, unref, onScopeDispose, watch, type Ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useUserStore } from '@/stores/user'
import { useCardDraft } from './useCardDraft'
import { useWorldStore } from '@/stores/world'
import type { CreateCardPayload, CardSummary } from '@/api/types/world'
import type { CardForm } from './useCardForm'
import { type CardType } from '@/views/世界观管理/card_type'
import type { AttributeItem } from '@/views/世界观管理/card_type'

export function useCardEditor(
  form: Ref<CardForm>,
  resetForm: () => void,
  setFormData: (data: Partial<CardForm>) => void,
  checkQuota: () => Promise<boolean>,
  projectId: Ref<string> | string = ''
) {
  const route = useRoute()
  const store = useWorldStore()

  const draft = useCardDraft(form)
  watch(() => useUserStore().token, () => { loadVersion++; draft.suspend(); resetForm(); loadError.value = true }, { flush: 'sync' })

  const saving = ref(false)
  const loading = ref(false)
  const loadError = ref(false)
  let loadVersion = 0
  const isCreating = ref(true)
  const snapshot = () => JSON.stringify(form.value)
  const savedSnapshot = ref(snapshot())
  const markClean = () => { savedSnapshot.value = snapshot() }
  const isDirty = computed(() => !loading.value && !loadError.value && snapshot() !== savedSnapshot.value)

  // 仅显式传入的条目决定编辑目标，阅读页路由不能覆盖新建表单。
  const currentCardId = ref<string>('')

  // 优先使用传入的 projectId，如果没有则从路由获取
  const routeProjectId = computed(() => unref(projectId) || String(route.params.projectId || route.params.id || ''))
  const routeCardId = computed(() => currentCardId.value || undefined)

  const startCreating = () => {
    loadVersion++
    draft.suspend()
    resetForm()
    isCreating.value = true
    currentCardId.value = ''
    loading.value = false
    loadError.value = false
    markClean()
    draft.bind(routeProjectId.value, '')
  }

  // ===== 加载卡片数据 =====
  const loadCardData = async (cardData?: Pick<CardSummary, 'id'> | null) => {
    const version = ++loadVersion
    draft.suspend()
    const cardId = cardData?.id
    if (!cardId) {
      startCreating()
      return
    }

    // ✅ 记住当前卡片 ID
    currentCardId.value = cardId
    isCreating.value = false
    loadError.value = false

    const pid = routeProjectId.value
    if (!pid) {
      throw new Error('缺少 projectId')
    }

    loading.value = true
    try {
      // 表单使用独立副本，未保存的图库、引用和时间线不能改动阅读缓存。
      const fullCard = JSON.parse(JSON.stringify(await store.fetchCardDetail(pid, cardId)))
      if (version !== loadVersion) return

      if (!fullCard) {
        throw new Error('卡片数据为空')
      }

      const rawAttributes = fullCard.attributes || []
      const attributes: AttributeItem[] = rawAttributes.map((attr: AttributeItem) => ({
        key: attr.key,
        value: attr.value,
        type: (['short', 'long', 'number', 'date', 'boolean'].includes(attr.type) ? attr.type : 'short') as AttributeItem['type'],
      }))

      const relations = (fullCard.outRelations || []).map((r: { targetCardId: string; relationType: string }) => ({
        targetCardId: r.targetCardId,
        relationType: r.relationType,
      }))

      // ✅ 解析 content 字符串 → 对象
      let parsedContent: Record<string, any> = {}
      try {
        const raw = fullCard.content
        if (raw) {
          const parsed = JSON.parse(raw)
          if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
            parsedContent = parsed
          }
        }
      } catch (err) {
        console.warn('解析 content 失败，使用空对象:', err)
        parsedContent = {}
      }

      setFormData({
        title: fullCard.title || '',
        type: fullCard.type as CardType,
        coverImage: fullCard.coverImage || '',
        galleryImages: fullCard.galleryImages || [],
        attributes,
        description: fullCard.description || '',
        content: parsedContent,   // ✅ 对象
        tags: Array.isArray(fullCard.tags) ? fullCard.tags : [],
        relations,
        contentBlocks: fullCard.contentBlocks || [],
        timelineEvents: fullCard.timelineEvents || [],
      })
      markClean()
      draft.bind(pid, cardId)

    } catch (error) {
      if (version !== loadVersion) return
      console.error('加载卡片数据失败:', error)
      loadError.value = true
    } finally {
      if (version === loadVersion) loading.value = false
    }
  }

  // ===== 保存卡片 =====
  const handleSave = async (onSaved: (cardId: string) => void) => {
    if (saving.value || loading.value || loadError.value || draft.pending.value) return
    if (!form.value.title.trim()) {
      ElMessage.warning('请输入标题')
      return
    }

    saving.value = true
    const version = loadVersion
    const pid = routeProjectId.value
    try {
      if (isCreating.value) {
        const canCreate = await checkQuota()
        if (version !== loadVersion) return
        if (!canCreate) {
          ElMessage.warning('当前世界卡片数量已达上限，请扩容')
          return
        }
      }

      const cardPayload: CreateCardPayload = {
        title: form.value.title.trim(),
        type: form.value.type,
        coverImage: form.value.coverImage,
        galleryImages: form.value.galleryImages,
        attributes: form.value.attributes.map(attribute => ({ ...attribute, value: String(attribute.value ?? '') })),
        description: form.value.description.trim(),
        content: JSON.stringify(form.value.content || {}),   // ✅ 对象 → 字符串
        tags: form.value.tags,
        contentBlocks: form.value.contentBlocks,
        timelineEvents: form.value.timelineEvents,
        relations: form.value.relations,
      }

      if (isCreating.value) {
        const created = await store.createCard(pid, cardPayload)
        if (version !== loadVersion) return
        currentCardId.value = created.id
        isCreating.value = false
        ElMessage.success('已创建')
      } else {
        if (!currentCardId.value) throw new Error('缺少卡片 ID')
        await store.updateCard(currentCardId.value, cardPayload)
        ElMessage.success('已更新')
      }

      if (version === loadVersion) { draft.acceptSaved(); markClean(); onSaved(currentCardId.value) }
    } catch (error: any) {
      console.error('保存失败:', error)
      if (error?.response?.data?.code === 'CARD_LIMIT_EXCEEDED') {
        ElMessage.warning({
          message: error.response.data.message || '卡片数量已达上限，请扩容',
          duration: 5000,
          showClose: true,
        })
      } else {
        ElMessage.error(error?.response?.data?.message || '保存失败，填写的内容已保留，请重试')
      }
    } finally {
      saving.value = false
    }
  }

  // ===== 删除卡片 =====
  const handleDelete = async (onDeleted: () => void) => {
    try {
      await ElMessageBox.confirm('确定删除吗？', '提示', { type: 'warning' })
      const cardId = currentCardId.value
      if (!cardId) {
        throw new Error('缺少卡片 ID')
      }
      await store.deleteCard(cardId)
      draft.acceptSaved()
      markClean()
      ElMessage.success('已删除')
      onDeleted()
    } catch (error) {
      if (error !== 'cancel') console.error(error)
    }
  }

  onScopeDispose(() => { loadVersion++ })
  return {
    draft,
    isDirty,
    markClean,
    saving,
    loading,
    loadError,
    isCreating,
    routeProjectId,
    routeCardId,
    currentCardId,
    startCreating,
    loadCardData,
    handleSave,
    handleDelete,
  }
}

// src/composables/世界观管理/useCardForm.ts
import { ref } from 'vue'
import type { CardType, AttributeItem, ContentBlock } from '@/views/世界观管理/card_type'

function createEmptyCardForm() {
  return {
    title: '',
    type: 'character' as CardType,
    coverImage: '',
    galleryImages: [] as string[],
    attributes: [] as AttributeItem[],
    description: '',
    content: {} as Record<string, any>,   // ✅ 对象
    tags: [] as string[],
    relations: [] as { targetCardId: string; relationType: string }[],
    contentBlocks: [] as ContentBlock[],
    timelineEvents: [] as { date: string; era?: string | null; title: string; description: string | null }[],
  }
}

export type CardForm = ReturnType<typeof createEmptyCardForm>

export function useCardForm() {
  const form = ref(createEmptyCardForm())
  const resetForm = () => { form.value = createEmptyCardForm() }

  // 批量设置表单数据（用于加载已有卡片）
  const setFormData = (data: Partial<typeof form.value>) => {
    Object.assign(form.value, data)
  }

  return {
    form,
    resetForm,
    setFormData,
  }
}

import assert from 'node:assert/strict'
import { before, beforeEach, after, test } from 'node:test'
import { fileURLToPath } from 'node:url'
import { createServer } from 'vite'
import vue from '@vitejs/plugin-vue'
import { createPinia, setActivePinia } from 'pinia'
import { createSSRApp, h, effectScope, ref, nextTick } from 'vue'
import { renderToString } from '@vue/server-renderer'
import { createRouter, createMemoryHistory } from 'vue-router'

const root = fileURLToPath(new URL('../', import.meta.url))
const componentPath = '/src/views/世界观管理/世界观组件/'
const date = '2026-10-21T00:00:00Z'
const card = (id, projectId = 'a', extra = {}) => ({ id, projectId, title: id, type: 'character',
  subType: null, coverImage: null, createdAt: date, updatedAt: date, description: null, content: '{}',
  aliases: [], attributes: [], contentBlocks: [], timelineEvents: [], tags: [], embeddedCards: [],
  galleryImages: [], outRelations: [], inRelations: [], ...extra })
const block = (id, order = 0) => ({ id: `block-${id}`, cardId: id, cardType: 'character', order })
const project = id => ({ id, name: '测试世界', description: '世界简介', isPublic: true,
  createdAt: date, updatedAt: date, cardCount: 2, ownerName: '作者', ownerId: 'owner' })
const deferred = () => {
  let resolve, reject
  const promise = new Promise((ok, fail) => { resolve = ok; reject = fail })
  return { promise, resolve, reject }
}
const settle = async () => { await nextTick(); await new Promise(resolve => setImmediate(resolve)) }
let server, pinia, worldApi, useWorldStore, useUserStore, presentation, graph, useCardPreload,
  useCardPresentation, useImagePreview, useExpandedItems, originalApi
const scopes = []
function inScope(setup) {
  const scope = effectScope()
  scopes.push(scope)
  return { value: scope.run(setup), stop: () => scope.stop() }
}

before(async () => {
  server = await createServer({ root, configFile: false, envDir: false, plugins: [vue()],
    resolve: { alias: { '@': `${root}src` } },
    server: { middlewareMode: true, hmr: false, ws: false, watch: null, fs: { allow: [root] } },
    optimizeDeps: { noDiscovery: true, include: [] },
  })
  ;({ worldApi } = await server.ssrLoadModule('/src/api/worldApi.ts'))
  ;({ useWorldStore } = await server.ssrLoadModule('/src/stores/world.ts'))
  ;({ useUserStore } = await server.ssrLoadModule('/src/stores/user.ts'))
  presentation = await server.ssrLoadModule('/src/utils/worldPresentation.ts')
  graph = await server.ssrLoadModule('/src/utils/worldGraph.ts')
  ;({ useCardPreload } = await server.ssrLoadModule('/src/composables/世界观管理/useCardPreload.ts'))
  ;({ useCardPresentation } = await server.ssrLoadModule('/src/composables/世界观管理/useCardPresentation.ts'))
  ;({ useImagePreview } = await server.ssrLoadModule('/src/composables/世界观管理/useImagePreview.ts'))
  ;({ useExpandedItems } = await server.ssrLoadModule('/src/composables/世界观管理/useExpandedItems.ts'))
  originalApi = { ...worldApi }
})
beforeEach(() => {
  scopes.splice(0).forEach(scope => scope.stop())
  const values = new Map()
  globalThis.localStorage = { getItem: key => values.get(key) ?? null,
    setItem: (key, value) => values.set(key, String(value)), removeItem: key => values.delete(key) }
  pinia = createPinia()
  setActivePinia(pinia)
  useUserStore().setSession('fixture-token')
  Object.assign(worldApi, originalApi, { getProject: async id => project(id),
    getCards: async pid => [card('one', pid), card('two', pid)], getProjectRelations: async () => [],
    getCard: async (pid, id) => card(id, pid) })
})
after(async () => {
  scopes.forEach(scope => scope.stop())
  await server?.close()
})

test('legacy image/tag fields retain URL, array and JSON compatibility', () => {
  const { parseCoverImage, parseStringArray } = presentation
  assert.equal(parseCoverImage('https://example.test/a.jpg'), 'https://example.test/a.jpg')
  assert.equal(parseCoverImage('["a.jpg","b.jpg"]'), 'a.jpg')
  for (const value of [null, '', '[]', '{}']) assert.equal(parseCoverImage(value), '')
  assert.deepEqual(parseStringArray('["神话","奇幻"]'), ['神话', '奇幻'])
  assert.deepEqual(parseStringArray(['标签']), ['标签'])
  assert.deepEqual(parseStringArray('invalid json'), [])
  assert.deepEqual(parseStringArray('[null,1,"有效"]'), ['有效'])
})

test('navigation preserves type order, title order, case-insensitive search and empty groups', () => {
  const cards = [card('Zeta', 'a', { type: 'item' }), card('Alpha'), card('beta'), card('unknown', 'a', { type: 'custom' })]
  const groups = presentation.groupWorldCards(cards)
  assert.deepEqual(groups.map(group => [group.label, group.cards.map(card => card.id)]),
    [['角色', ['Alpha', 'beta']], ['物品', ['Zeta']], ['custom', ['unknown']]])
  assert.deepEqual(presentation.groupWorldCards(cards, ' ALP ')[0].cards.map(card => card.id), ['Alpha'])
  assert.deepEqual(presentation.groupWorldCards(cards, 'missing'), [])
  assert.equal(presentation.getCardTypeLabel('custom'), 'custom')
})

test('document and standalone detail retain their distinct embedded-reference rules', () => {
  const source = card('root', 'a', { contentBlocks: [block('one'), block('one'), block('two')],
    description: '{CARD:two} {CARD:three}' })
  assert.deepEqual(presentation.getEmbeddedCardIds(source), ['one', 'two'])
  assert.deepEqual(presentation.getEmbeddedCardIds(source, true), ['one', 'two', 'three'])
})

test('nested cards stop at the depth limit and exclude self and ancestor cycles', () => {
  const blocks = [block('root'), block('parent'), block('child')]
  assert.deepEqual(presentation.getNestedBlocks(blocks, 'root', ['parent'], 0, 2).map(b => b.cardId), ['child'])
  assert.deepEqual(presentation.getNestedBlocks(blocks, 'root', ['parent'], 1, 2), [])
  assert.equal(presentation.getNestedBlocks([{ ...block('child'), id: '' }], 'root', [], 0, 2)[0].blockId, 'child-0')
})

test('inline reference markup retains each view format and escapes substituted titles', () => {
  const find = id => id === 'one' ? card(id, 'a', { title: '<img src=x>' }) : undefined
  assert.equal(presentation.renderCardDescription('<p>{CARD:one}</p>', find, 'document'),
    '&lt;p&gt;<a class="inline-ref" data-card-id="one">@角色 &lt;img src=x&gt;</a>&lt;/p&gt;')
  assert.equal(presentation.renderCardDescription('{CARD:one}', find, 'detail'),
    '<a class="inline-ref" data-card-id="one">@角色: &lt;img src=x&gt;</a>')
  assert.match(presentation.renderCardDescription('{CARD:deleted}', find, 'detail'), /已删除的卡片/)
})

test('graph retains explicit-edge priority and excludes missing/self embedded targets', () => {
  const cards = [card('one'), card('two'), card('three')]
  const relations = [{ sourceCardId: 'one', targetCardId: 'two', relationType: '朋友' },
    { sourceCardId: 'one', targetCardId: 'deleted', relationType: '丢失' }]
  const result = graph.buildWorldGraph(cards, relations, id => card(id, 'a', {
    contentBlocks: id === 'one' ? ['one', 'two', 'three', 'deleted'].map(block) : [] }))
  assert.equal(result.nodes.length, 3)
  assert.deepEqual(result.links.map(edge => [edge.source, edge.target, edge.isEmbed]),
    [['one', 'two', false], ['one', 'three', true]])
  assert.equal(result.links[0].label, '朋友')
  assert.equal(graph.getGraphTypeColor('organization'), '#7c3aed')
  assert.equal(graph.getGraphTypeColor('creature'), '#84cc16')
  assert.equal(graph.getGraphTypeColor('concept'), '#6366f1')
})

test('graph camera maintains the viewing distance including nodes at the origin', () => {
  for (const node of [{}, { x: 0, y: 0, z: 0 }, { x: 3, y: 4, z: 0 }]) {
    const { position, target } = graph.getNodeCameraPosition(node)
    assert.ok(Object.values(position).every(Number.isFinite))
    assert.ok(Math.abs(Math.hypot(position.x - target.x, position.y - target.y, position.z - target.z) - 100) < 0.001)
  }
})

test('preloads share Store requests/cache without changing the selected card', async () => {
  const store = useWorldStore()
  await store.fetchCards('a')
  await store.fetchCardDetail('a', 'one')
  let calls = 0
  worldApi.getCard = async (pid, id) => { calls++; return card(id, pid) }
  const first = inScope(() => useCardPreload('a')).value
  const second = inScope(() => useCardPreload('a')).value
  await Promise.all([first.load(['', 'one', 'two', 'two']), second.load(['two'])])
  assert.equal(calls, 1)
  assert.equal(first.loading.value, false)
  assert.equal(first.getDetail('two').id, 'two')
  assert.equal(store.currentCard.id, 'one')
})

test('project switches stop subsequent preload batches and cannot mix caches', async () => {
  const pid = ref('a'), ids = ref(Array.from({ length: 10 }, (_, i) => String(i)))
  const pending = deferred(), requested = []
  worldApi.getCard = async (projectId, id) => {
    requested.push(`${projectId}:${id}`)
    if (projectId === 'a') await pending.promise
    return card(id, projectId)
  }
  const loader = inScope(() => useCardPreload(pid, ids)).value
  assert.equal(loader.loading.value, true)
  assert.equal(requested.length, 8)
  pid.value = 'b'; ids.value = ['new']
  await settle()
  assert.equal(loader.getDetail('new').projectId, 'b')
  pending.resolve(); await settle()
  assert.equal(requested.includes('a:8'), false)
  assert.equal(loader.getDetail('0'), null)
  assert.equal(loader.loading.value, false)
})

test('disposing a preload stops queued work and resets loading', async () => {
  const pending = deferred(), requested = []
  worldApi.getCard = async (pid, id) => { requested.push(id); await pending.promise; return card(id, pid) }
  const scope = inScope(() => useCardPreload('a'))
  const task = scope.value.load(Array.from({ length: 10 }, (_, i) => String(i)))
  scope.stop(); pending.resolve(); await task
  assert.equal(requested.length, 8)
  assert.equal(scope.value.loading.value, false)
})

test('a failed preload does not hide successful cards and can be retried', async () => {
  const originalWarn = console.warn
  console.warn = () => {}
  let fail = true
  worldApi.getCard = async (pid, id) => {
    if (id === 'two' && fail) throw new Error('fixture failure')
    return card(id, pid)
  }
  try {
    const loader = inScope(() => useCardPreload('a')).value
    await loader.load(['one', 'two'])
    assert.equal(loader.getDetail('one').id, 'one')
    assert.equal(loader.getDetail('two'), null)
    assert.equal(loader.loading.value, false)
    fail = false; await loader.load(['two'])
    assert.equal(loader.getDetail('two').id, 'two')
  } finally { console.warn = originalWarn }
